from __future__ import absolute_import
import os
import time
import re
from .exceptions import TimeoutException, TooManyFilesFoundException


class Downloader(object):
    def __init__(self):
        """
        Download engine

        """
        self.download_timeout = None
        self.begin_time = None
        self.end_time = None
        self.step = None

    def download(self, download_dir, start_downloading_time, pattern='', download_timeout=1200, step=1):
        """
        Waits until expecting file is downloaded for given download timeout. When file
        is downloaded it returns its path together with the filename.
        Otherwise, when no file was detected during given timeout it raises TimeoutException and
        when more than one file was detected it raises TooManyFilesException.

        .. note:: Case when more than one downloaded file was detected can occur when some
        file was added to the download directory during downloading process.

        :param download_dir: path to download dir
        :param start_downloading_time: timestamp just before starting download process
        :param pattern: (optional) regex pattern of downloading file
        :param download_timeout: time to wait until download is completed
        :param step: time periods defining how often tests against existing of downloading
        file should happen. In case of big files step should be higher than in case of smaller one
        :return: path to downloaded file
        :raises TimeoutException: when file can not be downloaded during given
        download_timeout time span
        :raises TooManyFilesException: when more than one downloaded file is detected
        """
        self.step = step
        self.download_timeout = download_timeout
        self.begin_time = start_downloading_time
        self.end_time = self.begin_time + self.download_timeout
        return self._wait_until_file_downloads(pattern, os.path.expanduser(download_dir))

    def _wait_until_file_downloads(self, pattern, download_dir):
        """
        Waits for any new file and when it is downloaded returns its
        path along with the name of file.

        :param download_dir: path to download dir
        :param pattern: regex pattern of downloading file
        :return: path to file
        :raises TimeoutException: when file can not be downloaded during given
        download_timeout time span
        """
        while True:
            path_to_downloaded_file_name = self._get_downloaded_file(pattern, download_dir)
            if path_to_downloaded_file_name:
                return path_to_downloaded_file_name
            if time.time() > self.end_time:
                raise TimeoutException('File could not be downloaded.')
            time.sleep(self.step)

    def _get_downloaded_file(self, pattern, download_dir):
        """
        Returns downloaded file's path.

        :param download_dir: path to download dir
        :param pattern: regex pattern of downloading file
        :return: path to downloaded file without extension
        """
        matches = [re.search(pattern, f) for f in os.listdir(download_dir)]
        files = [os.path.join(download_dir, m.string) for m in matches if m is not None]
        return self._detect_downloaded_file(files)

    def _detect_downloaded_file(self, files):
        """
        Scans given files and returns latest out of them. The function relies on timestamps
        of files. The file is considered as 'downloaded' when its timestamp (creation time)
        is greater than time just before downloading time. If more than two files are
        considered as downloaded the TooManyFilesException is raises.

        .. note:: The function ignores every '.part' files

        :param files: list of files to be scan through
        :return: path to latest downloaded file if downloaded file detected or
        None otherwise
        :raises TooManyFilesException: when more than one downloaded file is detected
        """
        downloaded_file = None
        for f in files:
            if self._is_file_considered_as_downloaded(f):
                if downloaded_file:
                    raise TooManyFilesFoundException(
                        'Found more than one file considered as downloaded files: {} and {}. '
                        'One of them probably was added accidentally added during test '
                        'execution.'.format(downloaded_file, f))
                downloaded_file = f
        return downloaded_file

    def _is_file_considered_as_downloaded(self, path):
        """
        Checks whether given file is considered as downloaded file by checking its timestamp
        and compering it with beginning time of downloading procedure.

        ..note:: Function considers only files and does not directories

        :param path: path to file to be checked
        :return: True if checking file is considered as downloaded or False otherwise
        """
        if os.path.isfile(path) and os.path.getmtime(path) > self.begin_time and not path.endswith('.part'):
            return True
        return False
